NUMS = r'\d{1,4}(?:(?:,? (?:and|or) |, )\d{1,4})*'
ROWS = r"\b(?:gap-ledger |ledger )?[Rr]ows? (" + NUMS + r")\b(?![’']s)"
FIX_DONE = r'(?:fixed|repaired|closed|resolved)'
